interface SimpleApiKeyProviderProps {
  provider: ProviderConfig;
  configured: boolean;
  onSave: (apiKey: string) => Promise<void>;
  onDelete: () => Promise<void>;
}

export function SimpleApiKeyProvider({ provider, configured, onSave, onDelete }: SimpleApiKeyProviderProps) {
  const [apiKey, setApiKey] = useState('');
  const [showKey, setShowKey] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      await onSave(apiKey);
      setApiKey(''); // Clear after save
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-3 pt-3">
      <p className="text-xs text-zinc-500">{provider.description}</p>

      {/* API Key Input */}
      <div className="flex items-center gap-2">
        <div className="relative flex-1">
          <input
            type={showKey ? "text" : "password"}
            value={apiKey}
            onChange={(e) => setApiKey(e.target.value)}
            placeholder={`Enter your ${provider.name} API key`}
            className="w-full px-3 py-2 text-sm border border-zinc-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500"
          />
          <button
            type="button"
            onClick={() => setShowKey(!showKey)}
            className="absolute right-2 top-1/2 -translate-y-1/2 text-zinc-400 hover:text-zinc-600"
          >
            {showKey ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
          </button>
        </div>
      </div>

      {/* Get key link */}
      <a 
        href={provider.getKeyUrl}
        target="_blank"
        rel="noopener noreferrer"
        className="inline-flex items-center gap-1 text-xs text-purple-600 hover:text-purple-700"
      >
        Get your API key <ExternalLink className="w-3 h-3" />
      </a>

      {/* Actions */}
      <div className="flex items-center gap-2 pt-2">
        <button
          onClick={handleSave}
          disabled={!apiKey || isSaving}
          className="px-3 py-1.5 text-xs font-medium text-white bg-zinc-900 rounded-lg hover:bg-zinc-800 disabled:opacity-50"
        >
          {isSaving ? 'Saving...' : 'Save'}
        </button>
        {configured && (
          <button
            onClick={onDelete}
            className="px-3 py-1.5 text-xs font-medium text-red-600 hover:bg-red-50 rounded-lg"
          >
            Remove
          </button>
        )}
      </div>
    </div>
  );
}
