 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { authAPI } from '@/lib/api/client';

export interface ApiKeyInfo {
  id: string;
  provider: string;
  keyPreview: string | null;
  isValid: boolean;
  createdAt: string;
  lastUsedAt: string | null;
}

export const apiKeyKeys = {
  all: ['apiKeys'] as const,
  list: () => [...apiKeyKeys.all, 'list'] as const,
};

/**
 * Hook to list all API keys for the current user
 */
export function useApiKeys() {
  return useQuery({
    queryKey: apiKeyKeys.list(),
    queryFn: async () => {
      const response = await authAPI.fetch('/api/api-keys');
      if (!response.ok) {
        throw new Error('Failed to fetch API keys');
      }
      const data = await response.json();
      return data.keys as ApiKeyInfo[];
    },
    staleTime: 5 * 60 * 1000, // 5 minutes
  });
}

/**
 * Hook to save an API key for a provider
 */
export function useSaveApiKey() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ provider, apiKey }: { provider: string; apiKey: string }) => {
      const response = await authAPI.fetch(`/api/api-keys/${provider}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ apiKey }),
      });

      if (!response.ok) {
        const error = await response.json().catch(() => ({ error: 'Failed to save API key' }));
        throw new Error(error.error || 'Failed to save API key');
      }

      return response.json();
    },
    onSuccess: () => {
      // Invalidate and refetch the keys list
      queryClient.invalidateQueries({ queryKey: apiKeyKeys.list() });
    },
  });
}

/**
 * Hook to delete an API key for a provider
 */
export function useDeleteApiKey() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (provider: string) => {
      const response = await authAPI.fetch(`/api/api-keys/${provider}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error('Failed to delete API key');
      }

      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: apiKeyKeys.list() });
    },
  });
}

/**
 * ProvidersTab - Main container for provider API key settings
 * 
 * Displays providers organized into collapsible sections:
 * - Simple API Keys (Anthropic, OpenAI, Google, etc.)
 * - Cloud Providers (Bedrock, Azure)
 * - Local Providers (Ollama)
 */
import { useState } from 'react';
import { ChevronDown } from 'lucide-react';
import { SimpleKeyProvider } from './SimpleKeyProvider';
import { LocalProvider } from './LocalProvider';
import { 
  SIMPLE_KEY_PROVIDERS, 
  CLOUD_PROVIDERS, 
  LOCAL_PROVIDERS,
  type ProviderConfig 
} from '@/lib/providers-config';
import { useApiKeys, useSaveApiKey, useDeleteApiKey, type ApiKeyInfo } from '@/hooks/useApiKeys';

interface ProviderSectionProps {
  title: string;
  providers: ProviderConfig[];
  keys: ApiKeyInfo[] | undefined;
  defaultFolded?: boolean;
  onSave: (provider: string, apiKey: string) => Promise<void>;
  onDelete: (provider: string) => Promise<void>;
  isSaving: boolean;
  deletingProvider: string | null;
}

function ProviderSection({ 
  title, 
  providers, 
  keys, 
  defaultFolded = false,
  onSave,
  onDelete,
  isSaving,
  deletingProvider 
}: ProviderSectionProps) {
  const [isExpanded, setIsExpanded] = useState(!defaultFolded);

  return (
    <div className="border border-zinc-200 rounded-xl overflow-hidden">
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="w-full flex items-center justify-between px-4 py-3 bg-zinc-50 hover:bg-zinc-100 transition-colors"
      >
        <span className="text-sm font-medium text-zinc-900">{title}</span>
        <ChevronDown 
          className={`w-4 h-4 text-zinc-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`} 
        />
      </button>

      {isExpanded && (
        <div className="divide-y divide-zinc-100">
          {providers.map(provider => {
            const keyInfo = keys?.find(k => k.provider === provider.id);

            // Render based on auth type
            if (provider.authType === 'local') {
              return (
                <LocalProvider
                  key={provider.id}
                  provider={provider}
                />
              );
            }

            return (
              <SimpleKeyProvider
                key={provider.id}
                provider={provider}
                configured={!!keyInfo}
                keyPreview={keyInfo?.keyPreview || null}
                onSave={onSave}
                onDelete={onDelete}
                isSaving={isSaving}
                isDeleting={deletingProvider === provider.id}
              />
            );
          })}
        </div>
      )}
    </div>
  );
}

export function ProvidersTab() {
  const { data: keys, isLoading } = useApiKeys();
  const saveMutation = useSaveApiKey();
  const deleteMutation = useDeleteApiKey();

  const handleSave = async (provider: string, apiKey: string) => {
    await saveMutation.mutateAsync({ provider, apiKey });
  };

  const handleDelete = async (provider: string) => {
    await deleteMutation.mutateAsync(provider);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="w-5 h-5 border-2 border-zinc-300 border-t-purple-500 rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Description */}
      <p className="text-sm text-zinc-500">
        Configure API keys for AI providers. Your keys are encrypted and stored securely.
      </p>

      {/* Simple API Keys */}
      <ProviderSection
        title="API Keys"
        providers={SIMPLE_KEY_PROVIDERS}
        keys={keys}
        onSave={handleSave}
        onDelete={handleDelete}
        isSaving={saveMutation.isPending}
        deletingProvider={deleteMutation.variables || null}
      />

      {/* Cloud Providers */}
      <ProviderSection
        title="Cloud Providers"
        providers={CLOUD_PROVIDERS}
        keys={keys}
        defaultFolded={true}
        onSave={handleSave}
        onDelete={handleDelete}
        isSaving={saveMutation.isPending}
        deletingProvider={deleteMutation.variables || null}
      />

      {/* Local Providers */}
      <ProviderSection
        title="Local"
        providers={LOCAL_PROVIDERS}
        keys={keys}
        defaultFolded={true}
        onSave={handleSave}
        onDelete={handleDelete}
        isSaving={saveMutation.isPending}
        deletingProvider={deleteMutation.variables || null}
      />
    </div>
  );
}

/**
 * SimpleKeyProvider - Single API key input field
 */
import { useState } from 'react';
import { Eye, EyeOff, ExternalLink, ChevronRight, CheckCircle, AlertCircle } from 'lucide-react';
import type { ProviderConfig } from '@/lib/providers-config';

interface SimpleKeyProviderProps {
  provider: ProviderConfig;
  configured: boolean;
  keyPreview: string | null;
  onSave: (provider: string, apiKey: string) => Promise<void>;
  onDelete: (provider: string) => Promise<void>;
  isSaving: boolean;
  isDeleting: boolean;
}

export function SimpleKeyProvider({ 
  provider, 
  configured, 
  keyPreview,
  onSave, 
  onDelete,
  isSaving,
  isDeleting
}: SimpleKeyProviderProps) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [apiKey, setApiKey] = useState('');
  const [showKey, setShowKey] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSave = async () => {
    if (!apiKey.trim()) return;

    setError(null);
    try {
      await onSave(provider.id, apiKey);
      setApiKey(''); // Clear after successful save
    } catch (err) {
      setError((err as Error).message);
    }
  };

  const handleDelete = async () => {
    setError(null);
    try {
      await onDelete(provider.id);
    } catch (err) {
      setError((err as Error).message);
    }
  };

  const handleToggle = () => {
    setIsExpanded(!isExpanded);
    setError(null);
  };

  return (
    <div className="group">
      {/* Header - always visible */}
      <button
        onClick={handleToggle}
        className="w-full flex items-center justify-between px-4 py-3 hover:bg-zinc-50 transition-colors text-left"
      >
        <div className="flex items-center gap-3">
          {/* Provider icon placeholder */}
          <div className="w-8 h-8 rounded-lg bg-zinc-100 flex items-center justify-center">
            <span className="text-xs font-bold text-zinc-500">
              {provider.name.substring(0, 2).toUpperCase()}
            </span>
          </div>

          <div className="flex-1">
            <div className="flex items-center gap-2">
              <span className="text-sm font-medium text-zinc-900">{provider.name}</span>
              {configured ? (
                <span className="inline-flex items-center gap-1 px-2 py-0.5 text-xs font-medium text-emerald-700 bg-emerald-50 rounded-full">
                  <CheckCircle className="w-3 h-3" />
                  Ready
                </span>
              ) : (
                <span className="inline-flex items-center gap-1 px-2 py-0.5 text-xs font-medium text-zinc-500 bg-zinc-100 rounded-full">
                  <AlertCircle className="w-3 h-3" />
                  Not set
                </span>
              )}
            </div>
            {configured && keyPreview && (
              <span className="text-xs text-zinc-400 mt-0.5 block">
                Key: {keyPreview}...
              </span>
            )}
          </div>
        </div>

        <ChevronRight 
          className={`w-4 h-4 text-zinc-400 transition-transform ${isExpanded ? 'rotate-90' : ''}`} 
        />
      </button>

      {/* Expandable content */}
      {isExpanded && (
        <div className="px-4 pb-4 pt-2 border-t border-zinc-100">
          <p className="text-xs text-zinc-500 mb-3">{provider.description}</p>

          {/* API Key Input */}
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <div className="relative flex-1">
                <input
                  type={showKey ? 'text' : 'password'}
                  value={apiKey}
                  onChange={(e) => setApiKey(e.target.value)}
                  placeholder={`Enter your ${provider.name} API key`}
                  className="w-full px-3 py-2 text-sm border border-zinc-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500/20 focus:border-purple-500 pr-10"
                />
                <button
                  type="button"
                  onClick={() => setShowKey(!showKey)}
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-zinc-400 hover:text-zinc-600"
                >
                  {showKey ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                </button>
              </div>
            </div>

            {/* Get key link */}
            {provider.getKeyUrl && (
              <a
                href={provider.getKeyUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-1 text-xs text-purple-600 hover:text-purple-700"
              >
                Get your API key <ExternalLink className="w-3 h-3" />
              </a>
            )}
          </div>

          {/* Error message */}
          {error && (
            <p className="text-xs text-red-600 mt-2">{error}</p>
          )}

          {/* Actions */}
          <div className="flex items-center gap-2 mt-3">
            <button
              onClick={handleSave}
              disabled={!apiKey.trim() || isSaving}
              className="px-3 py-1.5 text-xs font-medium text-white bg-zinc-900 rounded-lg hover:bg-zinc-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {isSaving ? 'Saving...' : 'Save'}
            </button>
            {configured && (
              <button
                onClick={handleDelete}
                disabled={isDeleting}
                className="px-3 py-1.5 text-xs font-medium text-red-600 hover:bg-red-50 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {isDeleting ? 'Removing...' : 'Remove'}
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

