## Detailed Implementation

### 1. Create `apps/server/src/pi/model-config.ts` (New File)

This module configures Pi AI models with user-provided API keys, supporting both simple key providers and complex ones (AWS, Azure).

```typescript
/**
 * Model Configuration with User API Keys
 * 
 * Provides functions to configure Pi AI models with user-provided
 * API keys stored in the database (BYOK model).
 */

import { getModel, setProviderConfig, type Model } from '@mariozechner/pi-ai';
import { getApiKey } from '../auth/api-keys.js';
import { loadPiConfig, PROVIDER_ENV_KEYS, PROVIDER_ALIAS } from './config.js';

export interface ApiKeySource {
  userId: string;
  provider: string;
}

/**
 * Configure a provider with the user's API key.
 * Falls back to environment variable if no user key.
 * 
 * This MUST be called before getModel() for providers that need
 * runtime configuration (AWS, Azure, etc.)
 */
export async function configureProviderWithUserKey(
  userId: string,
  provider: string
): Promise<{ configured: boolean; keySource: 'user' | 'env' | 'none' }> {
  const mappedProvider = PROVIDER_ALIAS[provider] || provider;
  const config = loadPiConfig();

  // 1. Try to get user's API key from database
  const userKey = await getApiKey(userId, provider);

  if (userKey) {
    // Configure provider with user's key
    await setProviderConfig(mappedProvider as any, {
      apiKey: userKey,
    });
    console.log(`[ModelConfig] Using user's API key for ${provider}`);
    return { configured: true, keySource: 'user' };
  }

  // 2. Check for environment variable
  const envKeys = PROVIDER_ENV_KEYS[mappedProvider] || [];
  const hasEnvKey = envKeys.some(k => process.env[k]);

  if (hasEnvKey) {
    console.log(`[ModelConfig] Using environment key for ${provider}`);
    return { configured: true, keySource: 'env' };
  }

  // 3. No key available
  console.warn(`[ModelConfig] No API key configured for ${provider}`);
  return { configured: false, keySource: 'none' };
}

/**
 * Configure AWS Bedrock with user credentials.
 * 
 * Supports two auth modes:
 * 1. Profile - AWS profile name from ~/.aws/credentials
 * 2. Credentials - Access Key ID + Secret Access Key + Region
 */
export async function configureBedrockProvider(
  userId: string
): Promise<{ configured: boolean; error?: string }> {
  const userKey = await getApiKey(userId, 'amazon-bedrock');

  if (userKey) {
    try {
      // User key is stored as JSON with credentials
      const credentials = JSON.parse(userKey);

      if (credentials.authMode === 'profile') {
        // Configure for profile-based auth
        await setProviderConfig('amazon-bedrock', {
          profile: credentials.profile || 'default',
        });
      } else {
        // Configure for key-based auth
        await setProviderConfig('amazon-bedrock', {
          accessKeyId: credentials.accessKey,
          secretAccessKey: credentials.secretKey,
          region: credentials.region || 'us-east-1',
        });
      }

      console.log('[ModelConfig] Configured Bedrock with user credentials');
      return { configured: true };
    } catch (err) {
      console.error('[ModelConfig] Failed to parse Bedrock credentials:', err);
      return { configured: false, error: 'Invalid Bedrock credentials format' };
    }
  }

  // Check for environment credentials (AWS_ACCESS_KEY_ID, etc.)
  if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
    console.log('[ModelConfig] Using environment credentials for Bedrock');
    return { configured: true };
  }

  return { configured: false, error: 'No Bedrock credentials configured' };
}

/**
 * Configure Azure OpenAI with user credentials.
 */
export async function configureAzureProvider(
  userId: string
): Promise<{ configured: boolean; error?: string }> {
  const userKey = await getApiKey(userId, 'azure-openai');

  if (userKey) {
    try {
      const credentials = JSON.parse(userKey);

      await setProviderConfig('azure-openai-responses', {
        apiKey: credentials.apiKey,
        resourceName: credentials.resourceName,
        deploymentName: credentials.deploymentName,
        apiVersion: credentials.apiVersion || '2024-12-01-preview',
      });

      console.log('[ModelConfig] Configured Azure OpenAI with user credentials');
      return { configured: true };
    } catch (err) {
      console.error('[ModelConfig] Failed to parse Azure credentials:', err);
      return { configured: false, error: 'Invalid Azure credentials format' };
    }
  }

  // Check for environment credentials
  if (process.env.AZURE_OPENAI_API_KEY) {
    console.log('[ModelConfig] Using environment credentials for Azure');
    return { configured: true };
  }

  return { configured: false, error: 'No Azure credentials configured' };
}

/**
 * Get a configured model for a provider, using user's API key.
 * 
 * This is the main entry point for getting models with user credentials.
 */
export async function getConfiguredModel(
  userId: string,
  provider: string,
  modelId: string
): Promise<{ model: Model<any> | null; error?: string }> {
  const mappedProvider = PROVIDER_ALIAS[provider] || provider;

  // Handle complex providers differently
  if (mappedProvider === 'amazon-bedrock') {
    const result = await configureBedrockProvider(userId);
    if (!result.configured) {
      return { model: null, error: result.error };
    }
  } else if (mappedProvider === 'azure-openai-responses') {
    const result = await configureAzureProvider(userId);
    if (!result.configured) {
      return { model: null, error: result.error };
    }
  } else {
    // Simple API key providers
    const result = await configureProviderWithUserKey(userId, provider);
    if (!result.configured) {
      return { 
        model: null, 
        error: `No API key configured for ${provider}. Add your key in Settings > Providers.` 
      };
    }
  }

  // Get the model
  try {
    const model = getModel(mappedProvider as any, modelId as any);
    return { model };
  } catch (err) {
    return { model: null, error: `Model not found: ${provider}/${modelId}` };
  }
}
```

### 2. Add Streaming Endpoint to `apps/server/src/routes/chats.ts`

Add a new POST endpoint for streaming:

```typescript
// Add imports at the top
import { runPiQuery } from '../pi/index.js';
import { getConfiguredModel } from '../pi/model-config.js';
import { getOrCreateWorkspaceSession, getComposioClient } from '../index.js';
import { buildWorkspaceTools } from '../pi/tools/index.js';
import type { StreamChunk } from '@normie/types';

// ============================================
// STREAM CHAT (Pi Agent Endpoint)
// ============================================
interface StreamChatBody {
  message: string;
  provider: string;
  model: string;
  workspaceId?: string;
}

router.post('/:chatId/stream', async (req: Request, res: Response) => {
  const chatId = req.params.chatId as string;
  const { message, provider, model, workspaceId } = req.body as StreamChatBody;

  // Validate required fields
  if (!message || !provider || !model) {
    return res.status(400).json({ 
      error: 'message, provider, and model are required' 
    });
  }

  const db = getDb();

  // Get chat and verify access
  const [chat] = await db.select()
    .from(schema.chats)
    .where(eq(schema.chats.id, chatId));

  if (!chat) {
    return res.status(404).json({ error: 'Chat not found' });
  }

  // Verify workspace access
  const [workspace] = await db.select()
    .from(schema.workspaces)
    .where(eq(schema.workspaces.id, chat.workspaceId));

  const isOwner = workspace.ownerId === req.userId;

  if (!isOwner) {
    const [membership] = await db.select()
      .from(schema.workspaceMembers)
      .where(and(
        eq(schema.workspaceMembers.workspaceId, workspace.id),
        eq(schema.workspaceMembers.userId, req.userId!)
      ));

    if (!membership) {
      return res.status(403).json({ error: 'Access denied' });
    }
  }

  // Set up SSE headers
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no'); // Disable nginx buffering

  try {
    // 1. Configure model with user's API key
    const modelResult = await getConfiguredModel(req.userId!, provider, model);

    if (!modelResult.model) {
      const errorChunk: StreamChunk = {
        type: 'error',
        message: modelResult.error || 'Failed to configure model',
        provider,
      };
      res.write(`data: ${JSON.stringify(errorChunk)}\n\n`);
      res.end();
      return;
    }

    // 2. Save user message
    await db.insert(schema.messages).values({
      chatId,
      role: 'user',
      content: message,
    });

    // 3. Build conversation history
    const historyMessages = await db.select()
      .from(schema.messages)
      .where(eq(schema.messages.chatId, chatId))
      .orderBy(schema.messages.createdAt);

    const messages = historyMessages.map(msg => ({
      role: msg.role,
      content: msg.content,
    }));

    // 4. Get Composio client if workspace has integrations
    let composioClient: unknown = null;
    if (workspaceId) {
      try {
        const session = await getOrCreateWorkspaceSession(workspaceId, req.userId!);
        if (session) {
          composioClient = getComposioClient();
        }
      } catch (err) {
        console.warn('[STREAM] Composio not available:', (err as Error).message);
      }
    }

    // 5. Build system prompt (from workspace files)
    // TODO: Use context-builder for SOUL.md, MEMORY.md integration
    const systemPrompt = ''; // Placeholder for now

    // 6. Run Pi Agent query
    const abortController = new AbortController();

    // Handle client disconnect
    req.on('close', () => {
      abortController.abort();
    });

    let assistantResponse = '';

    for await (const chunk of runPiQuery({
      provider,
      model,
      workspaceId: workspaceId || chat.workspaceId,
      chatId,
      userId: req.userId!,
      systemPrompt,
      messages,
      composioClient,
      signal: abortController.signal,
    })) {
      // Send SSE event
      res.write(`data: ${JSON.stringify(chunk)}\n\n`);

      // Collect assistant response for saving
      if (chunk.type === 'text' && !chunk.isReasoning) {
        assistantResponse += chunk.content || '';
      }
    }

    // 7. Save assistant response
    if (assistantResponse) {
      await db.insert(schema.messages).values({
        chatId,
        role: 'assistant',
        content: assistantResponse,
      });

      // Update chat timestamp
      await db.update(schema.chats)
        .set({ updatedAt: new Date() })
        .where(eq(schema.chats.id, chatId));
    }

  } catch (error) {
    console.error('[STREAM] Error:', error);

    const errorChunk: StreamChunk = {
      type: 'error',
      message: (error as Error).message,
      provider,
    };
    res.write(`data: ${JSON.stringify(errorChunk)}\n\n`);
  } finally {
    res.end();
  }
});

// ============================================
// ABORT STREAM
// ============================================
router.post('/:chatId/abort', async (req: Request, res: Response) => {
  // Store abort controllers in a Map<chatId, AbortController>
  // This would need to be implemented with a global Map
  // For now, client-side abort is sufficient
  res.json({ success: true });
});
```

### 3. Update `electron/src/preload.ts`

Change the endpoint URL and body format:

```typescript
// Around line 403-430, update sendMessage function:

sendMessage: async (
  message: string,
  chatId: string,
  provider: string = 'claude',
  model: string | null = null,
  workspaceId: string | null = null,
  userId: string | null = null
): Promise<StreamResponse> => {
  // Abort any previous request
  if (currentAbortController) {
    currentAbortController.abort();
  }

  // Create new abort controller for this request
  currentAbortController = new AbortController();
  const signal = currentAbortController.signal;

  return new Promise((resolve, reject) => {
    console.log('[PRELOAD] Sending message to Pi Agent:', { chatId, provider, model });

    // CHANGED: Use new /api/chats/:chatId/stream endpoint
    fetch(`${SERVER_URL}/api/chats/${chatId}/stream`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      credentials: 'include',
      body: JSON.stringify({ 
        message, 
        provider, 
        model,
        workspaceId
      }),
      signal
    })
      .then(response => {
        if (!response.ok) {
          // Try to parse error response
          response.json().then(errData => {
            reject(new Error(errData.error || `HTTP ${response.status}`));
          }).catch(() => {
            reject(new Error(`HTTP error! status: ${response.status}`));
          });
          return;
        }

        console.log('[PRELOAD] Connected to Pi Agent successfully');

        // Return a custom object with methods to read the stream
        resolve({
          getReader: async function() {
            const reader = response.body!.getReader();
            const decoder = new TextDecoder();
            return {
              read: async () => {
                try {
                  const { done, value } = await reader.read();
                  if (done) {
                    console.log('[PRELOAD] Stream ended');
                  }
                  return {
                    done,
                    value: done ? undefined : decoder.decode(value, { stream: true })
                  };
                } catch (readError) {
                  if ((readError as Error).name === 'AbortError') {
                    console.log('[PRELOAD] Stream aborted by user');
                    return { done: true, value: undefined };
                  }
                  console.error('[PRELOAD] Read error:', readError);
                  throw readError;
                }
              }
            };
          }
        });
      })
      .catch(error => {
        console.error('[PRELOAD] Connection error:', error);
        reject(new Error(`Failed to connect to backend: ${error.message}`));
      });
  });
},
```

