  composioClient?: unknown;
  signal?: AbortSignal;
  sessionId?: string;
  /** Pre-resolved credentials (from request handler) */
  credentials?: ResolvedCredentials;
}

export async function* runPiQuery(
  options: RunPiQueryOptions
): AsyncGenerator<StreamChunk> {
  const {
    provider,
    model,
    workspaceId,
    chatId,
    userId,
    systemPrompt,
    messages,
    composioClient,
    signal,
    sessionId,
    credentials,
  } = options;

  console.log('[PiAgent] Running query:', { provider, model, workspaceId, chatId });

  // Get validated model (this just gets model metadata, doesn't need credentials)
  const piModel = getValidatedModel(provider, model);

