    includeWebTools: true,
    includeComposioTools: !!composioClient,
  });
  console.log('[PiAgent] Built tools:', tools.length);

  // Create getApiKey callback for per-request credential injection
  const getApiKeyCallback = credentials 
    ? createGetApiKeyCallback(credentials)
    : undefined;

  // Build stream options from credentials
  const streamOptions = credentials 
    ? buildStreamOptions(credentials)
    : {};

  // Create Agent with credentials callback
  const agent = new Agent({
    initialState: {
      systemPrompt: systemPrompt || '',
      model: piModel,
      tools,
      thinkingLevel: 'medium',
    },
    sessionId,
    // CRITICAL: Pass getApiKey callback for per-request credentials
    getApiKey: getApiKeyCallback,
    // Note: Additional stream options are passed via streamFn if needed
  });

  // ... rest of the implementation stays the same ...
  // (event queue, subscription, prompt loop, etc.)
}
